// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    function setUp() public { c = new Cooler(); }
    function testFuzz_property(address caller, address collateral_, address debt_) public {
        vm.assume(caller != address(0));
        vm.assume(collateral_ != address(0));
        vm.assume(debt_ != address(0));
        vm.assume(caller != address(this));
        vm.assume(collateral_ != address(c));
        vm.assume(debt_ != address(c));
        vm.assume(caller.code.length == 0);

        CoolerFactory factory = new CoolerFactory();
        vm.prank(caller);
        address clone = factory.generateCooler(ERC20(collateral_), ERC20(debt_));

        address owner = Cooler(clone).owner();
        assertTrue(owner == caller);
    }
}

interface ERC20 {
}

contract CoolerFactory {
    using ClonesWithImmutableArgs for address;

    Cooler public immutable coolerImplementation;
    mapping(address => bool) public created;

    constructor() {
        coolerImplementation = new Cooler();
    }

    function generateCooler(ERC20 collateral_, ERC20 debt_) external returns (address cooler) {
        bytes memory coolerData = abi.encodePacked(
            msg.sender,
            address(collateral_),
            address(debt_),
            address(this)
        );
        cooler = address(coolerImplementation).clone(coolerData);
        created[cooler] = true;
    }
}

contract Clone {
    function _getArgAddress(uint256 argOffset)
        internal
        pure
        returns (address arg)
    {
        uint256 offset = _getImmutableArgsOffset();
        assembly {
            arg := shr(0x60, calldataload(add(offset, argOffset)))
        }
    }

    function _getImmutableArgsOffset() internal pure returns (uint256 offset) {
        assembly {
            offset := sub(
                calldatasize(),
                add(shr(240, calldataload(sub(calldatasize(), 2))), 2)
            )
        }
    }
}

